#!/usr/bin/env python3

# Known table values from the MBR
table_values = [
    0x0270, 0x0211, 0x0255, 0x0229, 0x0291, 0x025e, 0x0233, 0x01f9,
    0x0278, 0x027b, 0x0221, 0x0209, 0x025d, 0x0290, 0x028f, 0x02df
]

# Known start of flag format: "flag{"
known_chars = "flag{"

def analyze_pattern():
    print("Analyzing transformation pattern...")
    print("\nKnown input vs table values:")

    for i, char in enumerate(known_chars):
        if i < len(table_values):
            print(f"Input char: '{char}' (0x{ord(char):02x}) -> Table value: 0x{table_values[i]:04x}")

            # Try to determine the transformation
            original = ord(char)
            transformed = table_values[i]

            # Calculate potential XOR key and shift
            for shift in range(8):
                for xor in range(256):
                    if ((original << shift) ^ xor) == transformed:
                        print(f"  Possible transformation: (char << {shift}) ^ 0x{xor:02x}")

# Attempt to reverse the transformation
def reconstruct_flag():
    # Based on analysis of first 5 characters ("flag{"), 
    # we can determine the transformation pattern
    # Let's try reverse engineering each byte

    reconstructed = ""

    # The pattern appears to be: value = (char << 1) ^ 0x20
    # So to reverse: char = (value ^ 0x20) >> 1

    for val in table_values:
        char = (val ^ 0x20) >> 1
        reconstructed += chr(char)

    print(f"\nReconstructed flag: {reconstructed}")
    return reconstructed

def main():
    analyze_pattern()
    flag = reconstruct_flag()

if __name__ == "__main__":
    main()

#!/usr/bin/env python3

# Known table values from the MBR
table_values = [
    0x0270, 0x0211, 0x0255, 0x0229, 0x0291, 0x025e, 0x0233, 0x01f9,
    0x0278, 0x027b, 0x0221, 0x0209, 0x025d, 0x0290, 0x028f, 0x02df
]

def reverse_transform(val):
    # Remove the 0x02/0x01 prefix
    val = val & 0xFF
    # XOR with a key to get ASCII value
    ascii_val = val ^ 0x20
    return chr(ascii_val)

def reconstruct_flag():
    flag = ""
    for val in table_values:
        flag += reverse_transform(val)
    return flag

flag = reconstruct_flag()
print(f"Reconstructed flag: {flag}")

#!/usr/bin/env python3

# Known table values from the MBR
table_values = [
    0x0270, 0x0211, 0x0255, 0x0229, 0x0291, 0x025e, 0x0233, 0x01f9,
    0x0278, 0x027b, 0x0221, 0x0209, 0x025d, 0x0290, 0x028f, 0x02df
]

def analyze_with_offset():
    print("Analyzing with offset adjustments...")

    # Try different base values to subtract
    for base in range(0x00, 0xFF):
        result = ""
        valid = True
        for val in table_values:
            low_byte = val & 0xFF
            adj_byte = (low_byte - base) & 0xFF
            if 32 <= adj_byte <= 126:  # Printable ASCII
                result += chr(adj_byte)
            else:
                valid = False
                break

        if valid:
            print(f"Base 0x{base:02x}: {result}")
            if "flag{" in result:
                print("*** Found possible flag pattern! ***")

print("Starting offset analysis...")
analyze_with_offset()

